// Daily configuration check of every watched domain. Compares each domain's DNS
// with the previous day's snapshot and with the expected values in the Domains tab,
// and warns before certificates expire. Like the other sweeps, it only alerts when
// a domain's findings change, so a known issue is reported once.
const CERT_WARN_DAYS = 14;
const BATCH = 5;
const TYPES = ['A', 'AAAA', 'CNAME', 'NS', 'MX', 'TXT'];
const TYPE_NUM = { 1: 'A', 28: 'AAAA', 5: 'CNAME', 2: 'NS', 15: 'MX', 16: 'TXT' };
const state = $getWorkflowStaticData('global');
state.snap = state.snap || {};
state.flags = state.flags || {};

const clean = (type, v) => {
  const s = String(v).replace(/^"|"$/g, '').replace(/"\s*"/g, '');
  return type === 'TXT' ? s : s.toLowerCase().replace(/\.$/, '');
};
const list = (v) => String(v ?? '').split(/[\s,]+/).map(x => x.trim().toLowerCase().replace(/\.$/, '')).filter(Boolean).sort();
const get = async (url) => {
  for (let attempt = 1; ; attempt++) {
    try {
      return await this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: 15000 });
    } catch (e) {
      if (attempt === 2) throw e;
    }
  }
};

const lookup = async (domain) => {
  const records = {};
  let nxdomain = false;
  for (const type of TYPES) {
    const r = await get('https://dns.google/resolve?name=' + encodeURIComponent(domain) + '&type=' + type);
    if (r.Status === 3) nxdomain = true;
    records[type] = [...new Set((r.Answer || []).filter(a => TYPE_NUM[a.type] === type).map(a => clean(type, a.data)))].sort();
  }
  return { records, nxdomain };
};

const certDays = async (domain) => {
  try {
    const r = await get('https://networkcalc.com/api/security/certificate/' + encodeURIComponent(domain));
    const validTo = r?.certificate?.valid_to;
    if (!validTo) return null;
    return { validTo, days: Math.floor((new Date(validTo) - Date.now()) / 86400000) };
  } catch (e) {
    return null;
  }
};

// Address records on a CDN can rotate a few at a time, so A/AAAA changes count only
// when the whole set is replaced. Every other record type is compared exactly.
const diff = (before, after) => {
  const changes = [];
  for (const type of TYPES) {
    const b = before[type] || [];
    const a = after[type] || [];
    const added = a.filter(x => !b.includes(x));
    const removed = b.filter(x => !a.includes(x));
    if (!added.length && !removed.length) continue;
    if ((type === 'A' || type === 'AAAA') && b.length && a.length && added.length < a.length) continue;
    const parts = [];
    if (removed.length) parts.push('removed ' + removed.join(' | '));
    if (added.length) parts.push('added ' + added.join(' | '));
    changes.push(type + ' ' + parts.join(', '));
  }
  return changes;
};

const ORDER = ['NS_MISMATCH', 'HOST_MISMATCH', 'DNS_CHANGED', 'CERT_EXPIRING', 'MULTIPLE_SPF'];
const rows = $input.all().map(i => i.json).filter(r => String(r.Domain ?? '').trim());
const seen = new Set();
const alerts = [];
const skipped = [];

const check = async (row) => {
  const domain = String(row.Domain).trim().toLowerCase();
  if (seen.has(domain)) return;
  seen.add(domain);
  let live;
  try {
    live = await lookup(domain);
  } catch (e) {
    skipped.push(domain);
    return;
  }
  const { records } = live;
  const findings = {};

  const expectedNs = list(row['Expected Nameservers']);
  if (expectedNs.length && !live.nxdomain && expectedNs.join(',') !== records.NS.join(',')) {
    findings.NS_MISMATCH = 'Nameservers are ' + (records.NS.join(', ') || 'missing') + ', expected ' + expectedNs.join(', ') + '.';
  }
  const expectedHost = list(row['Expected Host']);
  if (expectedHost.length) {
    const targets = [...records.A, ...records.AAAA, ...records.CNAME];
    if (!expectedHost.some(h => targets.some(t => t === h || t.endsWith('.' + h)))) {
      findings.HOST_MISMATCH = 'Points to ' + (targets.join(', ') || 'nothing') + ', expected ' + expectedHost.join(' or ') + '.';
    }
  }
  const spf = records.TXT.filter(t => /^v=spf1(\s|$)/i.test(t));
  if (spf.length > 1) findings.MULTIPLE_SPF = spf.length + ' SPF records found; receivers treat this as an SPF error.';
  const cert = await certDays(domain);
  if (cert && cert.days <= CERT_WARN_DAYS) {
    findings.CERT_EXPIRING = cert.days < 0
      ? 'Certificate expired on ' + cert.validTo + '.'
      : 'Certificate expires in ' + cert.days + ' day(s), on ' + cert.validTo + '.';
  }

  const before = state.snap[domain];
  const changes = before ? diff(before, records) : [];
  state.snap[domain] = records;

  // Persistent findings alert when they appear or clear; DNS changes alert once.
  const flagKey = Object.keys(findings).filter(k => k !== 'DNS_CHANGED').sort().join(',');
  const previous = state.flags[domain] ?? '';
  const flagsChanged = flagKey !== previous;
  if (flagKey) state.flags[domain] = flagKey; else delete state.flags[domain];
  if (changes.length) findings.DNS_CHANGED = 'DNS records changed since the previous daily check: ' + changes.join('; ') + '.';
  if (!changes.length && !flagsChanged) return;

  const current = ORDER.filter(k => findings[k]);
  if (!current.length) {
    alerts.push({ json: { domain, event_type: 'CONFIG_RESTORED', details: 'Daily config check: the earlier findings (' + previous + ') have cleared. Verify and resolve if appropriate.', source: 'n8n_config_sweep', severity_hint: 'unknown' } });
    return;
  }
  const lines = current.map(k => k + ': ' + findings[k]);
  const hint = findings.NS_MISMATCH || findings.HOST_MISMATCH ? 'high' : 'unknown';
  alerts.push({ json: { domain, event_type: current[0], details: 'Daily config check. ' + lines.join(' '), source: 'n8n_config_sweep', severity_hint: hint } });
};

for (let i = 0; i < rows.length; i += BATCH) {
  await Promise.all(rows.slice(i, i + BATCH).map(check));
}
if (skipped.length) console.log('Config sweep skipped (lookup failed): ' + skipped.join(', '));
return alerts;
